#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum SignalKind { Address, Data, Control, Clock, Carry, Video }
impl SignalKind { pub const fn css_class(self)->&'static str { match self { Self::Address=>"address",Self::Data=>"data",Self::Control=>"control",Self::Clock=>"clock",Self::Carry=>"carry",Self::Video=>"video" } } }

#[derive(Debug, Clone, Copy, PartialEq)]
pub struct Rect { pub x:f32,pub y:f32,pub w:f32,pub h:f32 }
impl Rect { pub const fn new(x:f32,y:f32,w:f32,h:f32)->Self{Self{x,y,w,h}} pub fn padded(self,p:f32)->Self{Self{x:self.x-p,y:self.y-p,w:self.w+2.0*p,h:self.h+2.0*p}} }

#[derive(Debug,Clone)] pub struct Group{pub id:String,pub label:String,pub bounds:Rect,pub assembly_rank:usize}
#[derive(Debug,Clone)] pub struct Node{pub id:String,pub title:String,pub kind:String,pub group:String,pub bounds:Rect}
#[derive(Debug,Clone)] pub struct Link{pub id:String,pub from:String,pub to:String,pub signal:SignalKind,pub label:String}
#[derive(Debug,Clone)] pub struct Topology{pub width:f32,pub height:f32,pub groups:Vec<Group>,pub nodes:Vec<Node>,pub links:Vec<Link>}
impl Topology{pub fn node(&self,id:&str)->Option<&Node>{self.nodes.iter().find(|n|n.id==id)} pub fn group(&self,id:&str)->Option<&Group>{self.groups.iter().find(|g|g.id==id)}}

pub fn build_topology()->Topology{
 let mut t=Topology{width:7000.0,height:3720.0,groups:vec![],nodes:vec![],links:vec![]};
 let gs=[
 ("clk","CLOCK / RESET",70.,110.,420.,460.,0),("pc","PROGRAM COUNTER + FETCH",520.,80.,650.,700.,1),("decode","INSTRUCTION DECODE / MICROCODE",1220.,70.,720.,790.,2),("regs","REGISTER FILE",780.,860.,1160.,650.,3),("alu","8-BIT ALU — FULL-ADDER SLICES",1980.,640.,1040.,1000.,4),("romsys","PROGRAM ROM — 8 KiB / 32 PAGES",3090.,80.,1280.,1120.,5),("ramsys","WORK RAM — 24 KiB / 96 PAGES",3090.,1240.,2000.,1700.,6),("bus","SYSTEM BUS / ARBITRATION",3090.,3000.,2050.,620.,7),("vramsys","VIDEO RAM — 2 KiB / 8 PAGES",5140.,1240.,1030.,920.,8),("io","INPUT / IRQ / TIMER",960.,1570.,980.,540.,9),("gpu","GPU / DMA / VIDEO SCANOUT",5200.,80.,1650.,1100.,10)];
 for(g,l,x,y,w,h,r)in gs{group(&mut t,g,l,Rect::new(x,y,w,h),r)}
 node(&mut t,"clock","CLOCK","OSC","clk",110.,165.,130.,90.);node(&mut t,"reset","RESET","SR LATCH","clk",110.,305.,130.,90.);node(&mut t,"clkGate","CLK GATE","AND","clk",300.,165.,110.,72.);
 for i in 0..3{node(&mut t,&format!("phase{i}"),&format!("T{i}"),"DFF","clk",300.,280.+i as f32*90.,90.,64.)}
 link(&mut t,"clk0","clock","clkGate",SignalKind::Clock,"CLK");link(&mut t,"rst0","reset","clkGate",SignalKind::Control,"RESET");link(&mut t,"clk1","clkGate","phase0",SignalKind::Clock,"CLK");link(&mut t,"clk2","phase0","phase1",SignalKind::Clock,"φ1");link(&mut t,"clk3","phase1","phase2",SignalKind::Clock,"φ2");
 for i in 0..16{node(&mut t,&format!("pcBit{i}"),&format!("PC{i}"),"DFF","pc",570.+(i%8)as f32*66.,150.+(i/8)as f32*125.,54.,46.);node(&mut t,&format!("marBit{i}"),&format!("MAR{i}"),"DFF","pc",960.+(i%8)as f32*62.,120.+(i/8)as f32*110.,52.,44.)}
 for(id,title,kind,x,y,w,h)in[("pcMuxLo","PC MUX LO","8× MUX",790.,190.,140.,88.),("pcMuxHi","PC MUX HI","8× MUX",790.,310.,140.,88.),("pcIncLo","INC LO","8× FA",790.,465.,140.,88.),("pcCarry","CARRY","OR",965.,500.,90.,60.),("pcIncHi","INC HI","8× FA",965.,360.,140.,88.)]{node(&mut t,id,title,kind,"pc",x,y,w,h)}
 for i in 0..8{link(&mut t,&format!("pcl{i}"),&format!("pcBit{i}"),"pcMuxLo",SignalKind::Data,"PC");link(&mut t,&format!("pch{i}"),&format!("pcBit{}",i+8),"pcMuxHi",SignalKind::Data,"PC");link(&mut t,&format!("mal{i}"),"pcMuxLo",&format!("marBit{i}"),SignalKind::Address,"A");link(&mut t,&format!("mah{i}"),"pcMuxHi",&format!("marBit{}",i+8),SignalKind::Address,"A")}
 link(&mut t,"pci0","pcBit0","pcIncLo",SignalKind::Data,"LO");link(&mut t,"pci1","pcIncLo","pcCarry",SignalKind::Carry,"C8");link(&mut t,"pci2","pcCarry","pcIncHi",SignalKind::Carry,"CARRY");
 for i in 0..8{node(&mut t,&format!("mdrBit{i}"),&format!("MDR{i}"),"DFF","decode",1240.+i as f32*64.,150.,52.,44.);node(&mut t,&format!("irBit{i}"),&format!("IR{i}"),"DFF","decode",1240.+i as f32*64.,240.,52.,44.);link(&mut t,&format!("mdi{i}"),&format!("mdrBit{i}"),&format!("irBit{i}"),SignalKind::Data,"OP")}
 for(id,title,kind,x,y,w,h)in[("opHi","IR[7:4]","SPLIT",1410.,300.,120.,70.),("opLo","IR[3:0]","SPLIT",1410.,390.,120.,70.),("decA","DECODER A","4→16",1600.,250.,140.,94.),("decB","DECODER B","4→16",1600.,390.,140.,94.),("microAddr","µADDR","MUX + CNT",1800.,220.,120.,82.),("microRom","CONTROL ROM","256×24",1800.,340.,120.,120.)]{node(&mut t,id,title,kind,"decode",x,y,w,h)}
 for(a,b)in[("irBit7","opHi"),("irBit3","opLo"),("opHi","decA"),("opLo","decB"),("decA","microAddr"),("decB","microAddr"),("microAddr","microRom")]{link(&mut t,&format!("d-{}-{b}",a),a,b,SignalKind::Control,"CTRL")}
 let regs=["A","B","X","Y","TMP","FLAGS","SPLO","SPHI"];for(ri,r)in regs.iter().enumerate(){for b in 0..8{node(&mut t,&format!("reg{r}{b}"),&format!("{r}{b}"),"DFF","regs",830.+(ri%4)as f32*270.+(b%4)as f32*58.,900.+(ri/4)as f32*300.+(b/4)as f32*86.,50.,42.)}}
 for(id,title,kind,x)in[("readMuxA","READ MUX A","8× 8:1 MUX",860.),("readMuxB","READ MUX B","8× 8:1 MUX",1150.),("writeDec","WRITE DEC","3→8",1500.),("writeBus","WRITE BUS","8-bit BUS",1730.)]{node(&mut t,id,title,kind,"regs",x,1350.,if id.starts_with("read") {210.}else{160.},90.)}
 for(ri,r)in regs.iter().enumerate(){for b in 0..8{let id=format!("reg{r}{b}");link(&mut t,&format!("ra{ri}-{b}"),&id,"readMuxA",SignalKind::Data,"R");if(ri+b)%2==0{link(&mut t,&format!("rb{ri}-{b}"),&id,"readMuxB",SignalKind::Data,"R")}link(&mut t,&format!("rw{ri}-{b}"),"writeBus",&id,SignalKind::Data,"W")}}
 node(&mut t,"aluSel","ALU SELECT","4-bit LATCH","alu",2050.,700.,160.,86.);for(id,title,y)in[("flagZ","ZERO FLAG",720.),("flagC","CARRY FLAG",830.),("flagN","NEG FLAG",940.)]{node(&mut t,id,title,"DFF","alu",2780.,y,150.,82.)}
 for i in 0..8{let y=815.+i as f32*94.;for(prefix,title,x,k)in[("xorA","XOR",2050.,"XOR"),("xorB","SUM",2180.,"XOR"),("andA","GEN",2310.,"AND"),("andB","PROP",2440.,"AND"),("orC","CARRY",2570.,"OR"),("muxR","RES",2700.,"MUX")]{node(&mut t,&format!("{prefix}{i}"),&format!("{title} {i}"),k,"alu",x,y,84.,54.)}link(&mut t,&format!("as{i}"),&format!("xorB{i}"),&format!("muxR{i}"),SignalKind::Data,"SUM");link(&mut t,&format!("ac{i}"),&format!("andA{i}"),&format!("orC{i}"),SignalKind::Carry,"C");if i<7{link(&mut t,&format!("cc{i}"),&format!("orC{i}"),&format!("xorB{}",i+1),SignalKind::Carry,"C")}}
 for(id,title,kind,x)in[("addrBuf","ADDRESS BUF","16× TRI",3160.),("dataBuf","DATA BUF","8× TRI",3380.),("ctrlBuf","CTRL BUF","RD/WR/IO",3600.),("arb","BUS ARBITER","CPU / DMA",3820.)]{node(&mut t,id,title,kind,"bus",x,3070.,150.,92.)}node(&mut t,"stackRam","STACK PAGE","256×8 SRAM","bus",4720.,3090.,190.,180.);
 node(&mut t,"romRowDec","ROM ROW DEC","5→32","romsys",3130.,150.,150.,82.);node(&mut t,"romByteDec","ROM BYTE DEC","8→256","romsys",3130.,270.,150.,82.);for p in 0..32{let id=format!("romPage{p}");node(&mut t,&id,&format!("ROM {p:02X}"),"256×8 SRAM","romsys",3340.+(p%8)as f32*125.,130.+(p/8)as f32*220.,110.,170.);link(&mut t,&format!("rc{p}"),"romRowDec",&id,SignalKind::Control,"CS");if p%2==0{link(&mut t,&format!("rd{p}"),&id,"dataBuf",SignalKind::Data,"D")}}
 node(&mut t,"ramPageDec","RAM PAGE DEC","7→96","ramsys",3130.,1320.,150.,82.);node(&mut t,"ramByteDec","RAM BYTE DEC","8→256","ramsys",3130.,1440.,150.,82.);for p in 0..96{let id=format!("ramPage{p}");node(&mut t,&id,&format!("RAM {p:02X}"),"256×8 SRAM","ramsys",3340.+(p%12)as f32*125.,1330.+(p/12)as f32*190.,110.,155.);if p%2==0{link(&mut t,&format!("mc{p}"),"ramPageDec",&id,SignalKind::Control,"CS")}if p%8==0{link(&mut t,&format!("md{p}"),&id,"dataBuf",SignalKind::Data,"D")}}
 node(&mut t,"vramPageDec","VRAM PAGE DEC","3→8","vramsys",5180.,1310.,150.,82.);node(&mut t,"vramByteDec","VRAM BYTE DEC","8→256","vramsys",5180.,1420.,150.,82.);for p in 0..8{let id=format!("vramPage{p}");node(&mut t,&id,&format!("VRAM {p}"),"256×8 SRAM","vramsys",5400.+(p%4)as f32*170.,1320.+(p/4)as f32*330.,150.,260.);link(&mut t,&format!("vc{p}"),"vramPageDec",&id,SignalKind::Control,"CS")}
 for(id,title,kind,x,y,w,h)in[("dmaAddr","DMA ADDR","16-bit CNT",5260.,170.,150.,86.),("dmaData","DMA DATA","8-bit LATCH",5260.,290.,150.,86.),("spriteRom","SPRITE ROM","16×8",5500.,170.,150.,100.),("xCounter","X COUNTER","7-bit CNT",5500.,330.,150.,86.),("yCounter","Y COUNTER","7-bit CNT",5500.,450.,150.,86.),("pixelMux","PIXEL MUX","8→1",5750.,330.,150.,86.),("scanShift","SCAN SHIFT","8-bit SHIFT",5750.,450.,150.,86.),("hsync","HSYNC","CMP",6010.,330.,110.,70.),("vsync","VSYNC","CMP",6010.,450.,110.,70.),("display","RGB332 SCREEN","128×96",6220.,260.,420.,300.)]{node(&mut t,id,title,kind,"gpu",x,y,w,h)}
 for(a,b,s)in[("dmaAddr","arb",SignalKind::Address),("dataBuf","dmaData",SignalKind::Data),("dmaData","spriteRom",SignalKind::Data),("spriteRom","pixelMux",SignalKind::Data),("xCounter","pixelMux",SignalKind::Video),("yCounter","pixelMux",SignalKind::Video),("pixelMux","scanShift",SignalKind::Data),("scanShift","display",SignalKind::Video),("xCounter","hsync",SignalKind::Clock),("yCounter","vsync",SignalKind::Clock),("hsync","display",SignalKind::Control),("vsync","display",SignalKind::Control)]{link(&mut t,&format!("g-{a}-{b}"),a,b,s,"GPU")}
 for(id,title,kind,x,y,w,h)in[("kbd","AUTOPILOT","INPUT DEVICE",1010.,1680.,170.,110.),("inputLatch","INPUT LATCH","8× DFF",1260.,1680.,170.,100.),("timer","FRAME TIMER","16-bit CNT",1510.,1680.,170.,100.),("irqAnd","IRQ GATE","AND",1740.,1680.,120.,80.),("irqLatch","IRQ LATCH","DFF",1740.,1810.,120.,80.)]{node(&mut t,id,title,kind,"io",x,y,w,h)}
 link(&mut t,"i0","kbd","inputLatch",SignalKind::Control,"INPUT");link(&mut t,"i1","inputLatch","dataBuf",SignalKind::Data,"PORT");link(&mut t,"i2","clock","timer",SignalKind::Clock,"CLK");link(&mut t,"i3","timer","irqAnd",SignalKind::Control,"IRQ");link(&mut t,"i4","irqAnd","irqLatch",SignalKind::Control,"IRQ");link(&mut t,"i5","irqLatch","microAddr",SignalKind::Control,"VECTOR");
 for(a,b,s)in[("addrBuf","romRowDec",SignalKind::Address),("addrBuf","ramPageDec",SignalKind::Address),("addrBuf","vramPageDec",SignalKind::Address)]{link(&mut t,&format!("bus-{b}"),a,b,s,"ADDR")}
 t
}
fn group(t:&mut Topology,id:&str,label:&str,bounds:Rect,assembly_rank:usize){t.groups.push(Group{id:id.into(),label:label.into(),bounds,assembly_rank})}
#[allow(clippy::too_many_arguments)]fn node(t:&mut Topology,id:&str,title:&str,kind:&str,group:&str,x:f32,y:f32,w:f32,h:f32){t.nodes.push(Node{id:id.into(),title:title.into(),kind:kind.into(),group:group.into(),bounds:Rect::new(x,y,w,h)})}
fn link(t:&mut Topology,id:&str,from:&str,to:&str,signal:SignalKind,label:&str){t.links.push(Link{id:id.into(),from:from.into(),to:to.into(),signal,label:label.into()})}

#[cfg(test)]mod tests{use super::*;use std::collections::HashSet;#[test]fn topology_is_large_and_closed(){let t=build_topology();assert!(t.nodes.len()>=300);assert!(t.links.len()>=180);let ids:HashSet<_>=t.nodes.iter().map(|n|n.id.as_str()).collect();assert_eq!(ids.len(),t.nodes.len());for l in &t.links{assert!(ids.contains(l.from.as_str()),"missing {}",l.from);assert!(ids.contains(l.to.as_str()),"missing {}",l.to)}}}
